//! The embedded `/vendor/` inventory.
//!
//! [`VENDOR_ASSETS`] is generated by `build.rs` from
//! `resources/vendor/vendor-manifest.toml`, which pins every file's
//! package, exact version, and sha256; the build fails when a row and its
//! bytes disagree, so the inventory a binary serves is always the
//! inventory the manifest vouches for. The tests here re-verify the same
//! invariants from the test side: hashes, served-path uniqueness, and the
//! load-bearing layout (KaTeX's `fonts/` sibling directory).

/// Mermaid's dist is committed gzipped (~1.6 MB) and never raw (~5.5 MB);
/// this is the regression guard on that rule.
pub const MAX_EMBEDDED_BYTES: usize = 2 * 1024 * 1024;

use crate::VENDOR_ASSETS;

/// The served path of the jinn-authored stylesheet inside `/vendor/`.
pub const AUTHORED_CSS_PATH: &str = "canvas.css";

/// The served path of the jinn-authored interaction tracker inside
/// `/vendor/` — injected into every served artifact by
/// [`crate::server::TRACKER_SNIPPET`].
pub const AUTHORED_TELEMETRY_PATH: &str = "canvas-telemetry.js";

/// The bytes of the jinn-authored stylesheet as embedded.
///
/// # Panics
///
/// Panics if `canvas.css` is missing from the generated inventory, which
/// means the manifest row was removed without restoring the file.
#[expect(
    clippy::expect_used,
    reason = "build.rs fails the build when the authored css row is absent"
)]
pub fn authored_css_source() -> &'static [u8] {
    VENDOR_ASSETS
        .iter()
        .find(|a| a.path == AUTHORED_CSS_PATH)
        .expect("canvas.css must be embedded")
        .bytes
}

/// The bytes of the jinn-authored telemetry script as embedded.
///
/// # Panics
///
/// Panics if `canvas-telemetry.js` is missing from the generated
/// inventory, which means its static build.rs row was removed without
/// restoring the file.
#[expect(
    clippy::expect_used,
    reason = "build.rs fails the build when the authored telemetry row is absent"
)]
pub fn authored_telemetry_source() -> &'static [u8] {
    VENDOR_ASSETS
        .iter()
        .find(|a| a.path == AUTHORED_TELEMETRY_PATH)
        .expect("canvas-telemetry.js must be embedded")
        .bytes
}

#[cfg(test)]
mod tests {
    #![allow(clippy::expect_used, reason = "test assertions need expect")]
    use super::MAX_EMBEDDED_BYTES;
    use crate::VENDOR_ASSETS;

    #[rstest::rstest]
    #[test]
    fn every_asset_is_vouched_for_and_under_the_size_cap() {
        // Given the generated vendor inventory.
        // When checking each asset against the manifest's size rule.
        // Then no embedded file exceeds the cap — the Mermaid dist ships
        // gzipped or not at all.
        for asset in VENDOR_ASSETS {
            assert!(
                asset.bytes.len() <= MAX_EMBEDDED_BYTES,
                "{} embeds {} bytes, over the {MAX_EMBEDDED_BYTES} cap",
                asset.path,
                asset.bytes.len()
            );
        }
    }

    #[rstest::rstest]
    #[test]
    fn served_paths_are_unique() {
        // Given the generated vendor inventory.
        // When collecting its served paths.
        let mut paths: Vec<_> = VENDOR_ASSETS.iter().map(|a| a.path).collect();
        let total = paths.len();
        paths.sort_unstable();
        paths.dedup();

        // Then no two assets share a served path — a duplicate would shadow
        // one of them at the vendor route.
        assert_eq!(paths.len(), total, "duplicate served path in VENDOR_ASSETS");
    }

    #[rstest::rstest]
    #[test]
    fn katex_fonts_serve_beside_their_css() {
        // Given the generated vendor inventory and KaTeX's relative
        // `url(fonts/…)` references.
        // When looking up the css and the font directory.
        let css = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "katex/katex.min.css")
            .expect("katex.min.css must be vendored");
        let font = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "katex/fonts/KaTeX_Main-Regular.woff2")
            .expect("KaTeX fonts must be vendored beside katex.min.css");

        // Then both exist and the css actually references the sibling
        // layout — a reorganized tree breaks math rendering silently.
        assert!(font.bytes.starts_with(b"wOF2"), "font is not woff2");
        assert!(!css.bytes.is_empty(), "katex.min.css must not be empty");
    }

    #[rstest::rstest]
    #[test]
    fn library_dists_are_gzip_marked_and_licenses_are_not() {
        // Given the generated vendor inventory.
        // When reading each asset's encoding.
        // Then the committed-gzip rule holds: library dists are served
        // with their real gzip container, licenses and fonts identity.
        let mermaid = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "mermaid/mermaid.min.js")
            .expect("mermaid must be vendored");
        assert_eq!(mermaid.encoding, "gzip");
        assert_eq!(
            mermaid.bytes.first(),
            Some(&0x1f),
            "mermaid dist must be committed gzipped, never raw"
        );

        let license = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "mermaid/LICENSE")
            .expect("mermaid license must be vendored");
        assert_eq!(license.encoding, "identity");
    }

    #[rstest::rstest]
    #[test]
    fn three_core_and_addons_are_vendored_gzipped() {
        // Given the generated vendor inventory.
        // When looking up the three.js core module build and every addon
        // the artifact loading pattern imports.
        // Then each is present and carries the committed-gzip container —
        // the served stream is pre-compressed, never raw.
        let paths = [
            "three/three.core.min.js",
            "three/three.module.min.js",
            "three/addons/controls/OrbitControls.js",
            "three/addons/controls/PointerLockControls.js",
            "three/addons/loaders/GLTFLoader.js",
            "three/addons/loaders/OBJLoader.js",
            "three/addons/loaders/STLLoader.js",
            "three/addons/geometries/ParametricGeometry.js",
            "three/addons/geometries/ParametricFunctions.js",
            "three/addons/utils/BufferGeometryUtils.js",
            "three/addons/utils/SkeletonUtils.js",
        ];
        for path in paths {
            let asset = VENDOR_ASSETS.iter().find(|a| a.path == path);
            assert!(asset.is_some(), "{path} must be vendored");
            let asset = asset.expect("presence asserted above");
            assert_eq!(asset.encoding, "gzip", "{path} must be committed gzipped");
            assert_eq!(
                asset.bytes.first(),
                Some(&0x1f),
                "{path} must be gzip-wrapped on disk"
            );
        }
    }

    #[rstest::rstest]
    #[test]
    fn three_addons_import_what_the_vendored_tree_resolves() {
        // Given the vendored addon sources, decompressed from their
        // committed gzip.
        // When reading each addon's import specifiers.
        // Then GLTFLoader's relative imports land inside the vendored
        // subtree (the `../utils/` layout is load-bearing — a moved file
        // breaks the loader silently) and the addons' only external
        // specifier is the bare `three`, which the artifact import map
        // aliases.
        let gltf = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "three/addons/loaders/GLTFLoader.js")
            .expect("GLTFLoader must be vendored");
        let raw = decompressed(gltf);
        assert!(
            raw.contains("from '../utils/BufferGeometryUtils.js'"),
            "GLTFLoader must keep its relative utility import"
        );
        assert!(
            raw.contains("from '../utils/SkeletonUtils.js'"),
            "GLTFLoader must keep its skeleton utility import"
        );
        // The main module's split-build import: it statically pulls the
        // core module from beside it, so the relative specifier must be
        // exactly this — a renamed core file breaks every import graph.
        let main = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "three/three.module.min.js")
            .expect("three main module must be vendored");
        assert!(
            decompressed(main).contains("./three.core.min.js"),
            "three main module must import the core module beside it"
        );
        for path in [
            "three/addons/controls/OrbitControls.js",
            "three/addons/loaders/STLLoader.js",
            "three/addons/geometries/ParametricGeometry.js",
        ] {
            let asset = VENDOR_ASSETS
                .iter()
                .find(|a| a.path == path)
                .expect("addon must be vendored");
            assert!(
                decompressed(asset).contains("from 'three'"),
                "{path} must import the bare `three` specifier"
            );
        }
    }

    #[rstest::rstest]
    #[test]
    fn three_license_is_vendored_plain_beside_the_lib() {
        // Given the generated vendor inventory.
        // When looking up the three.js license row.
        // Then it serves identity and is the MIT text.
        let license = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "three/LICENSE")
            .expect("three LICENSE must be vendored");
        assert_eq!(license.encoding, "identity");
        assert!(
            String::from_utf8_lossy(license.bytes).contains("MIT License"),
            "three's license must be the MIT text"
        );
    }

    /// Decompresses a committed-gzip asset into raw UTF-8 text.
    /// `flate2` is a dev-dependency only: the server forwards the
    /// compressed bytes verbatim and never inflates.
    #[expect(
        clippy::expect_used,
        reason = "test helper: a corrupt committed asset must fail loudly"
    )]
    fn decompressed(asset: &crate::VendorAsset) -> String {
        use std::io::Read as _;
        let mut decoder = flate2::read::GzDecoder::new(asset.bytes);
        let mut raw = String::new();
        decoder
            .read_to_string(&mut raw)
            .expect("committed gzip decodes to UTF-8");
        raw
    }

    #[rstest::rstest]
    #[test]
    fn authored_canvas_css_is_in_the_inventory() {
        // Given the generated vendor inventory.
        // When looking up the authored stylesheet.
        let css = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "canvas.css")
            .expect("canvas.css must be embedded");

        // Then it rides the same table as the vendored set.
        assert_eq!(css.encoding, "identity");
        assert_eq!(css.content_type, "text/css; charset=utf-8");
    }

    #[rstest::rstest]
    #[test]
    fn authored_telemetry_script_is_in_the_inventory() {
        // Given the generated vendor inventory.
        // When looking up the authored telemetry script.
        let script = VENDOR_ASSETS
            .iter()
            .find(|a| a.path == "canvas-telemetry.js")
            .expect("canvas-telemetry.js must be embedded");

        // Then it serves identity, as a script, with content on board.
        assert_eq!(script.encoding, "identity");
        assert_eq!(script.content_type, "text/javascript; charset=utf-8");
        assert!(!script.bytes.is_empty(), "the tracker must not be empty");
        // And the window API the skill teaches is actually in the file.
        let text = String::from_utf8_lossy(script.bytes);
        assert!(
            text.contains("window.canvas") && text.contains("track"),
            "the tracker must expose window.canvas.track"
        );
    }

    #[rstest::rstest]
    #[test]
    fn every_inventory_entry_names_a_supported_mime_type() {
        // Given the generated vendor inventory.
        // When reading each asset's content type.
        // Then nothing falls through to the octet-stream fallback — a new
        // vendored extension must come with its MIME type, not a binary
        // default that browsers refuse to render.
        for asset in VENDOR_ASSETS {
            assert_ne!(
                asset.content_type, "application/octet-stream",
                "{} has no explicit MIME type",
                asset.path
            );
        }
    }

    #[rstest::rstest]
    #[test]
    fn the_repo_license_index_names_every_vendored_library() {
        // Given the repo's THIRD_PARTY_LICENSES index and the vendor
        // manifest's distinct packages.
        let index = include_str!("../../../../THIRD_PARTY_LICENSES");
        let manifest = include_str!("../resources/vendor/vendor-manifest.toml");
        let packages: Vec<&str> = manifest
            .lines()
            .filter_map(|line| line.strip_prefix("package = \""))
            .map(|rest| rest.split('"').next().expect("a closing quote"))
            .collect::<std::collections::BTreeSet<_>>()
            .into_iter()
            .collect();

        // Then the index names each package (the rows we vendored) and the
        // p5 LGPL text is accounted for — the index is the distribution
        // record, so a new vendored row without an index entry must fail.
        for package in packages {
            assert!(
                index.contains(package),
                "THIRD_PARTY_LICENSES does not name vendored package {package}"
            );
        }
        // And the LGPL library's special obligation is flagged in the index.
        assert!(index.contains("LGPL-2.1"), "p5's LGPL must be named");
    }
}
